def _get_app_dir():
    try:
        if getattr(sys, 'frozen', False) or (len(sys.argv) > 0 and sys.argv[0].endswith('.exe')):
            return os.path.dirname(os.path.abspath(sys.argv[0]))
    except Exception:
        pass
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except Exception:
        return os.getcwd()

