def _write_log(msg):
    try:
        ts = time.strftime('%H:%M:%S')
        with _LOG_LOCK:
            with open(_LOG_FILE, 'a', encoding='utf-8') as f:
                f.write(f'[{ts}] {msg}\n')
    except Exception:
        pass

