# ─── Resource categorization ────────────────────────────────────────────
_ASSET_EXTS = {
    '.ydr', '.ydd', '.yft', '.ytd', '.ymt', '.ycd', '.ymap', '.ytyp',
    '.ybn', '.ynv', '.npi', '.awc', '.rel', '.ynd', '.ymf',
}
_ASSET_META_MARKERS = (
    'weapons.meta', 'weaponarchetypes', 'weaponcomponents',
    'carcols', 'carvariations', 'vehicles.meta', 'handling.meta',
    'componentpeds', 'pedpersonality',
)

def _categorize_resource(res):
    name  = res.get('name', '').lower()
    files = [k.lower() for k in res.get('files', {})]
    stream= [k.lower() for k in res.get('streamFiles', {})]
    all_f = files + stream
    exts  = {os.path.splitext(f)[1] for f in all_f}

    # A resource without any asset model/meta file is a pure script —
    # never a weapon/clothing/vehicle/map pack, even if its name contains
    # "weapon"/"car"/etc. (e.g. a Lua weapon shop/menu is a SCRIPT, not a pack).
    joined_files = ' '.join(files)
    has_asset_evidence = bool(exts & _ASSET_EXTS) or any(m in joined_files for m in _ASSET_META_MARKERS)
    if all_f and not has_asset_evidence:
        return 'script'

    # Weapons
    if (any(k in name for k in ('weapon', 'wpn_', 'gun_', 'rifle', 'pistol',
                                  'shotgun', 'ammo', 'silencer', 'suppressor'))
            or any('weapons.meta' in f or 'weaponarchetypes' in f for f in files)):
        return 'weapon'

    # Clothing / Ped
    if (any(k in name for k in ('cloth', 'outfit', 'ped_m', 'ped_f', 'hair_',
                                  'tattoo', 'tatoo', 'mask_', 'glasses', 'hat_',
                                  'shoes', 'pants', 'shirt', 'jacket', 'glove',
                                  'ring_', 'neck_', 'watch_', 'accessory'))
            or '.ydd' in exts
            or any('componentpeds' in f or 'pedpersonality' in f for f in files)):
        return 'clothe'

    # Vehicle / Car
    if (any(k in name for k in ('veh_', 'vehicle', 'bike_', 'boat_', 'plane_',
                                  'heli', 'truck_', 'aircraft', 'bus_', 'trailer'))
            or any('carcols' in f or 'carvariations' in f or 'vehicles.meta' in f
                   or 'handling.meta' in f for f in files)
            or ('.yft' in exts)):
        return 'car'

    # Maps / Interiors
    if ({'.ymap', '.ytyp', '.ybn', '.ynv', '.npi'} & exts
            or any(k in name for k in ('_mlo', 'interior', 'island', 'building',
                                        'garage', 'prison', 'casino', 'shop_', 'store_',
                                        '_map', 'map_', 'mlo_'))):
        return 'maps'

    return 'script'

# ─── WinAPI ───────────────────────────────────────────────────────────────
PROCESS_QUERY_INFORMATION = 0x0400
PROCESS_VM_READ           = 0x0010
MEM_COMMIT  = 0x1000
PAGE_GUARD  = 0x100
READABLE    = 0xEE

kernel32 = ctypes.WinDLL('kernel32')
SIZE_T = ctypes.c_size_t

class MEMORY_BASIC_INFORMATION(ctypes.Structure):
    _fields_ = [
        ('BaseAddress',       ctypes.c_void_p),
        ('AllocationBase',    ctypes.c_void_p),
        ('AllocationProtect', wintypes.DWORD),
        ('RegionSize',        ctypes.c_size_t),
        ('State',             wintypes.DWORD),
        ('Protect',           wintypes.DWORD),
        ('Type',              wintypes.DWORD),
    ]

VirtualQueryEx = kernel32.VirtualQueryEx
VirtualQueryEx.restype  = ctypes.c_size_t
VirtualQueryEx.argtypes = [wintypes.HANDLE, wintypes.LPCVOID,
                            ctypes.POINTER(MEMORY_BASIC_INFORMATION), SIZE_T]

ReadProcessMemory = kernel32.ReadProcessMemory
ReadProcessMemory.restype  = wintypes.BOOL
ReadProcessMemory.argtypes = [wintypes.HANDLE, wintypes.LPCVOID,
                               wintypes.LPVOID, SIZE_T, ctypes.POINTER(SIZE_T)]

_OpenProcess = kernel32.OpenProcess
_OpenProcess.restype  = wintypes.HANDLE
_OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]

_CloseHandle = kernel32.CloseHandle
_CloseHandle.restype  = wintypes.BOOL
_CloseHandle.argtypes = [wintypes.HANDLE]

def _addr(val):
    return val if val is not None else 0

# ─── License ──────────────────────────────────────────────────────────────
# Online verification through the Desktop API (api_licenses table) — no longer just a
# locally verified ECDSA signature. This allows a key to be revoked or its HWID reset
# (staff via /apilicense on Discord) and have it take effect on the next launch,
# which an offline signature could not do (it stayed valid forever).    
_LICENSE_FILE = os.path.join(os.path.expanduser('~'), '.cnc_license')

def get_hwid():
    # Attempt to get BIOS UUID first
    try:
        import subprocess
        output = subprocess.check_output("wmic csproduct get uuid", shell=True, stderr=subprocess.DEVNULL)
        uuid_str = output.decode().split()
        if len(uuid_str) >= 2 and len(uuid_str[1].strip()) > 5:
            return uuid_str[1].strip().upper()
    except Exception:
        pass
    # Fallback to MachineGuid
    try:
        import winreg
        registry_key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Cryptography", 0, winreg.KEY_READ | winreg.KEY_WOW64_64KEY)
        value, regtype = winreg.QueryValueEx(registry_key, "MachineGuid")
        winreg.CloseKey(registry_key)
        return str(value).strip().upper()
    except Exception:
        try:
            import winreg
            registry_key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Cryptography", 0, winreg.KEY_READ)
            value, regtype = winreg.QueryValueEx(registry_key, "MachineGuid")
            winreg.CloseKey(registry_key)
            return str(value).strip().upper()
        except Exception:
            pass
    # Absolute fallback
    try:
        import uuid
        return str(uuid.getnode()).upper()
    except Exception:
        return "UNKNOWN-HWID"

def verify_key(license_key, log=None):
    """Verify the key with the VPS (GET /api/license/verify — same api_licenses table
    as the decrypt/fix API). The HWID lock is handled server-side (COALESCE on first
    use) — a revoked key or a key whose HWID was reset stops/starts working
    immediately, without needing to issue a new key."""
    license_key = (license_key or '').strip()
    if not license_key:
        return None
    try:
        r = requests.get(
            f'{_VPS_API_URL}/api/license/verify',
            headers={'X-License-Key': license_key, 'X-Hwid': get_hwid()},
            timeout=15,
        )
        try:
            data = r.json()
        except Exception:
            data = {'ok': False, 'error': r.text[:200]}
        if r.status_code == 200 and data.get('ok'):
            return data
        if log:
            log(f'License check failed: {data.get("error", "HTTP " + str(r.status_code))}', 'err')
        return None
    except Exception as e:
        if log:
            log(f'License check error: {e}', 'err')
        return None

def load_stored_key():
    try:
        with open(_LICENSE_FILE, 'r') as f:
            return f.read().strip() or None
    except Exception:
        return None

def store_key(key):
    with open(_LICENSE_FILE, 'w') as f:
        f.write(key)

# ─── FiveM / RedM process ─────────────────────────────────────────────────
# Both games share the same CitizenFX engine (same in-memory token format,
# same cfx.re API) — only the target process and Cfx-Game-Name differ.
# We detect which one is running and never mix/hardcode both code paths:
# every game-specific value must come from this dict, not a fixed constant,
# otherwise the previous bug returns (one works while the other breaks).
_GAME_PROC_PATTERNS = [
    ('fivem', re.compile(r'FiveM(_b\d+)?_GTAProcess', re.IGNORECASE), 'gta5'),
    ('redm',  re.compile(r'RedM(_b\d+)?_GTAProcess',  re.IGNORECASE), 'rdr3'),
]

def find_fivem_process():
    """Detect the active FiveM OR RedM process. Returns a dict that also contains
    'game' ('fivem'/'redm') and 'game_name' ('gta5'/'rdr3') to drive the
    remaining logic (headers, cache paths) without hardcoding values."""
    for proc in psutil.process_iter(['pid', 'name']):
        try:
            name = proc.info['name']
            for game, pattern, game_name in _GAME_PROC_PATTERNS:
                if pattern.match(name):
                    info = dict(proc.info)
                    info['game']      = game
                    info['game_name'] = game_name
                    return info
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
    return None


# REPSCRIPTS process detection.
# Kept separate from FiveM/RedM token scanning: this only detects and displays
# whether the REPSCRIPTS launcher/client is running.
_REPSCRIPTS_PROC_PATTERNS = [
    re.compile(r'^REPSCRIPTS(?:\.exe)?$', re.IGNORECASE),
    re.compile(r'^REPSCRIPTS(?:_b\d+)?_GTAProcess(?:\.exe)?$', re.IGNORECASE),
]

def find_repscripts_process():
    for p in psutil.process_iter(['pid', 'name']):
        try:
            name = (p.info['name'] or '').lower()

            if name.startswith('repscripts'):
                return {
                    'pid': p.info['pid'],
                    'game': 'REPSCRIPTS',
                    'game_name': 'REPSCRIPTS'
                }
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass

    return None

# ─── Token + Ticket scan ──────────────────────────────────────────────────
_TOKEN_MARKER   = b'X-CitizenFX-Token: '
_TICKET_MARKER  = b'Cfx-Entitlement-Ticket: '
_TICKET_MARKER2 = b'Cfx-Entitlement-Ticket:'
# Only one memory scan can run at a time in the entire app — otherwise the background
# scan and the re-scan before download run in parallel (8 threads each) and
# saturate CPU/memory, causing latency.
_SCAN_LOCK = threading.Lock()

def _try_get_token(log=None, deep=False):
    def _log(msg, lvl='info'):
        if log: log(msg, lvl)
        _write_log(msg)

    if not _SCAN_LOCK.acquire(blocking=False):
        _log('Memory scan already in progress, skipped', 'dim')
        return None
    try:
        return _try_get_token_locked(_log, deep)
    finally:
        _SCAN_LOCK.release()

def _try_get_token_locked(_log, deep=False):
    proc = find_fivem_process()
    if not proc:
        _log('FiveM/RedM not detected', 'err'); return None

    handle = _OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, False, proc['pid'])
    if not handle:
        _log('OpenProcess failed — run as admin', 'err'); return None

    _log(f'Memory scan PID {proc["pid"]} ({proc["game"]})...')

    # Enumerate regions once, then sort by size (smaller = higher priority)
    address  = 0
    mbi      = MEMORY_BASIC_INFORMATION()
    high_prio = []
    low_prio  = []
    huge_prio = []  # regions > 16 MB — scanned only as a last resort
    while VirtualQueryEx(handle, ctypes.c_void_p(address), ctypes.byref(mbi), ctypes.sizeof(mbi)):
        if (mbi.State == MEM_COMMIT and
                not (mbi.Protect & PAGE_GUARD) and
                mbi.Protect & READABLE and
                mbi.RegionSize > 0):
            entry = (_addr(mbi.BaseAddress), mbi.RegionSize)
            if mbi.RegionSize <= 4 * 1024 * 1024:
                high_prio.append(entry)
            elif mbi.RegionSize <= 16 * 1024 * 1024:
                low_prio.append(entry)
            elif deep and mbi.RegionSize <= 64 * 1024 * 1024:
                huge_prio.append(entry)
        address = _addr(mbi.BaseAddress) + mbi.RegionSize

    found  = {}
    stop   = threading.Event()
    lock   = threading.Lock()

    def _extract(data, marker):
        idx = data.find(marker)
        if idx == -1:
            return ''
        start = idx + len(marker)
        end = start + 4096
        for stop in (b'\x00', b'\r', b'\n'):
            pos = data.find(stop, start)
            if pos != -1 and pos < end:
                end = pos
        val = data[start:end].decode('ascii', 'ignore').strip()
        return val if len(val) > 10 else ''

    def scan_region(base, size):
        if stop.is_set():
            return
        with lock:
            if found.get('token') and found.get('ticket'):
                stop.set()
                return
            need_tok = not found.get('token')
            need_tic = not found.get('ticket')
        buf = (ctypes.c_char * size)()
        n   = SIZE_T()
        if not ReadProcessMemory(handle, ctypes.c_void_p(base),
                                 ctypes.byref(buf), size, ctypes.byref(n)):
            return
        data = bytes(buf[:n.value])
        tok = _extract(data, _TOKEN_MARKER) if need_tok else ''
        tic = (_extract(data, _TICKET_MARKER) or
               _extract(data, _TICKET_MARKER2)) if need_tic else ''
        if tok or tic:
            with lock:
                if tok and not found.get('token'):
                    found['token'] = tok
                if tic and not found.get('ticket'):
                    found['ticket'] = tic
                if found.get('token') and found.get('ticket'):
                    stop.set()

    for batch in (high_prio, low_prio, huge_prio):
        if stop.is_set():
            break
        with ThreadPoolExecutor(max_workers=8) as exe:
            futs = {exe.submit(scan_region, base, sz) for base, sz in batch}
            for f in as_completed(futs):
                if stop.is_set():
                    break

    _CloseHandle(handle)

    if not found.get('token'):
        _log('Token not found — connect FiveM to a server', 'warn')
        return None

    token  = found['token']
    ticket = found.get('ticket', '')
    out    = {'token': token, 'pid': proc['pid'], 'game': proc['game'], 'game_name': proc['game_name']}
    if ticket:
        out['ticket'] = ticket
        _log(f'Token OK ({len(token)} chars) + Ticket OK ({len(ticket)} chars)', 'ok')
    else:
        _log(f'Token OK ({len(token)} chars) — no ticket', 'warn')
    return out

# ─── Resource memory scanner ───────────────────────────────────────────
PAT_URL = re.compile(
    rb'(https?://[a-zA-Z0-9._\-:]{4,80})/files/([a-zA-Z0-9][a-zA-Z0-9_\-]{1,50})'
    rb'/([^\x00\s"\'<>?#]{2,250})\?hash=([a-f0-9]{40,64})'
)
PAT_URI  = re.compile(rb'#[A-Za-z0-9+/=]{60,500}')
PAT_NAME = re.compile(rb'(?:[\x00\x01/"\'\\])([a-zA-Z][a-zA-Z0-9_\-]{2,39})(?:\x00|[/"\'\\])')
_SKIP = frozenset({
    'http','https','files','hash','name','type','data','json','utf8','ascii',
    'null','true','false','none','text','utf','gta5','fivem','citizenfx',
    'stream','client','server','resource','resources',
})
CDN_HOSTS = (
    'redsidecache.shieldcore.io','cfx-nui-storefront.akamaized.net',
    'nui-cdn.fivem.net','runtime.fivem.net',
)

def reconstruct_from_memory(pid, log):
    handle = _OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, False, pid)
    if not handle:
        log(f'OpenProcess failed PID {pid}', 'err'); return None

    address = 0
    mbi = MEMORY_BASIC_INFORMATION()
    res_files = {}; res_fs = {}; res_uris = {}; scanned = 0

    while VirtualQueryEx(handle, ctypes.c_void_p(address), ctypes.byref(mbi), ctypes.sizeof(mbi)):
        if (mbi.State == MEM_COMMIT and
                not (mbi.Protect & PAGE_GUARD) and
                mbi.Protect & READABLE and
                0 < mbi.RegionSize <= 512 * 1024 * 1024):
            buf = (ctypes.c_char * mbi.RegionSize)()
            n   = SIZE_T()
            if ReadProcessMemory(handle, ctypes.c_void_p(_addr(mbi.BaseAddress)),
                                 ctypes.byref(buf), mbi.RegionSize, ctypes.byref(n)):
                data = bytes(buf[:n.value])
                scanned += 1
                for m in PAT_URL.finditer(data):
                    try:
                        base  = m.group(1).decode('ascii', 'ignore')
                        rname = m.group(2).decode('ascii', 'ignore')
                        fpath = m.group(3).decode('ascii', 'ignore')
                        hsh   = m.group(4).decode('ascii', 'ignore')
                        if rname not in res_files:
                            res_files[rname] = {}
                            res_fs[rname]    = base + '/files'
                        res_files[rname][fpath] = hsh
                    except Exception:
                        pass
                for um in PAT_URI.finditer(data):
                    try:
                        uri = um.group(0).decode('ascii', 'ignore')
                        ctx = data[max(0, um.start()-400):um.start()]
                        for raw in reversed(PAT_NAME.findall(ctx)):
                            nm = raw.decode('ascii', 'ignore')
                            if 3 < len(nm) < 40 and nm.lower() not in _SKIP:
                                res_uris[nm] = uri; break
                    except Exception:
                        pass
        address = _addr(mbi.BaseAddress) + mbi.RegionSize

    _CloseHandle(handle)
    log(f'{scanned} regions — {len(res_files)} raw resources, {len(res_uris)} URIs')

    if not res_files and not res_uris:
        log('No URL found — is FiveM connected to a server?', 'err'); return None

    cnt    = Counter(res_fs.values())
    ip_cnt = Counter({fs: c for fs, c in cnt.items()
                      if re.match(r'https?://\d+\.\d+\.\d+\.\d+', fs)})
    dominant = ip_cnt.most_common(1)[0][0] if ip_cnt else (cnt.most_common(1)[0][0] if cnt else '')

    for nm in list(res_fs.keys()):
        if any(h in res_fs[nm] for h in CDN_HOSTS) and dominant:
            res_fs[nm] = dominant

    cnt2 = Counter(res_fs.values())
    dom2, dom_count = cnt2.most_common(1)[0] if cnt2 else ('', 0)
    log(f'Dominant fileServer: {dom2} ({dom_count} resources)')

    filtered_files = {nm: f for nm, f in res_files.items() if res_fs.get(nm) == dom2}
    filtered_uris  = {nm: u for nm, u in res_uris.items()  if nm in filtered_files}
    all_names = set(filtered_files) | set(filtered_uris)
    log(f'After filtering: {len(all_names)} resources, {len(filtered_uris)} encrypted')

    resources = []
    for nm in sorted(all_names):
        r = {'name': nm, 'files': filtered_files.get(nm, {}),
             'streamFiles': {}, 'fileServer': dom2}
        if nm in filtered_uris:
            r['uri'] = filtered_uris[nm]
        resources.append(r)
    return {'fileServer': dom2, 'resources': resources}


def resolve_cfx(join_code, log):
    link = f'https://cfx.re/join/{join_code}'
    try:
        r = requests.get(link, timeout=10, verify=False,
                         headers={'User-Agent': 'Mozilla/5.0'})
        ip = r.headers.get('x-citizenfx-url', '') or r.headers.get('X-CitizenFX-Url', '')
        if ip:
            ip = re.sub(r'^https?://', '', ip).rstrip('/')
            if ip:
                log(f'Server: {ip}', 'ok'); return ip
        hdrs_dbg = {k: v for k, v in r.headers.items() if 'citizen' in k.lower() or 'cfx' in k.lower()}
        log(f'Headers CFX: {hdrs_dbg}', 'dim')
    except Exception as e:
        log(f'cfx header: {e}', 'warn')
    try:
        r = requests.get(
            f'https://frontend.cfx-services.net/api/servers/single/{join_code}',
            timeout=10, verify=False)
        if r.status_code == 200:
            d = r.json().get('Data', r.json())
            eps = d.get('connectEndPoints', [])
            if eps:
                log(f'IP via API: {eps[0]}', 'ok'); return eps[0]
            log(f'API 200 but no endpoints (keys: {list(d.keys())[:5]})', 'warn')
        else:
            log(f'API HTTP {r.status_code}', 'dim')
    except Exception as e:
        log(f'API: {e}', 'warn')
    try:
        r = requests.get(link, timeout=8, allow_redirects=False, verify=False,
                         headers={'User-Agent': 'Mozilla/5.0'})
        loc = r.headers.get('Location', '')
        log(f'cfx.re redirect: {r.status_code} Location={loc[:80]}', 'dim')
        for pfx in ('fivem://connect/', 'redm://connect/', 'http://', 'https://'):
            if loc.startswith(pfx): loc = loc[len(pfx):]
        loc = loc.rstrip('/')
        if loc and ':' in loc and 'cfx.re' not in loc:
            log(f'IP via redirect: {loc}', 'ok'); return loc
    except Exception as e:
        log(f'Redirect: {e}', 'warn')
    return None


# ─── Session HTTP ─────────────────────────────────────────────────────────
def _make_session(token, ticket):
    from requests.adapters import HTTPAdapter
    s = requests.Session()
    s.verify = False
    # pool_maxsize must cover workers × res_workers (e.g. 6×3=18) plus margin
    adapter = HTTPAdapter(pool_connections=4, pool_maxsize=32)
    s.mount('http://', adapter)
    s.mount('https://', adapter)
    s.headers.update({
        'X-CitizenFX-Token': token,
        'User-Agent':        'CitizenFX/1',
        'Connection':        'keep-alive',
    })
    if ticket:
        s.headers['Cfx-Entitlement-Ticket'] = ticket
    s.cfx_token = token
    return s

def _quick_exists(url, session):
    _pace(urlparse(url).netloc)
    try:
        r = session.get(url, timeout=(3, 5), stream=True)
        r.close()
        return r.status_code != 404
    except Exception:
        return True

# ─── Adaptive anti-WAF rate limiter ──────────────────────────────────────
# Some file CDNs (evo-shield/PurpleMaze) cut connections and then blackhole the IP
# if too many requests are sent in a burst to their host
# (observed: ~20 requests in <1s -> complete timeout for several minutes).
# Most servers do not use this protection and work fine at full speed,
# so we throttle ONLY the host that just returned a network error, never the others.
# The throttle relaxes automatically once requests succeed again.
_pace_lock  = threading.Lock()
_pace_state = {}  # host -> {'next': float, 'interval': float}

def _pace(host):
    with _pace_lock:
        st = _pace_state.setdefault(host, {'next': 0.0, 'interval': 0.0})
        if st['interval'] <= 0:
            return
        now   = time.monotonic()
        delay = max(st['next'] - now, 0.0) + random.uniform(0.02, 0.06)
        st['next'] = now + delay + st['interval']
    if delay > 0:
        time.sleep(delay)

def _pace_penalize(host):
    """Network error detected on this host -> space requests out (backoff x1.6, cap 1.5s)."""
    with _pace_lock:
        st = _pace_state.setdefault(host, {'next': 0.0, 'interval': 0.0})
        st['interval'] = min(max(st['interval'], 0.15) * 1.6, 1.5)
        st['next'] = time.monotonic() + st['interval']

def _pace_relax(host):
    """Success on this host -> gradually relax the throttle."""
    with _pace_lock:
        st = _pace_state.get(host)
        if st and st['interval'] > 0:
            st['interval'] *= 0.85
            if st['interval'] < 0.08:
                st['interval'] = 0.0

# ─── Download ─────────────────────────────────────────────────────────────
_dbg_403 = [0]

def _tok_suffix(session):
    t = getattr(session, 'cfx_token', '')
    return f'&token={t}' if t else ''

def _invalid_file_server(fs):
    """Return a useful error for missing or placeholder resource endpoints."""
    parsed = urlparse(fs)
    if not fs or parsed.scheme not in ('http', 'https') or not parsed.hostname:
        return f'missing or malformed fileServer URL: {fs or "<empty>"}'
    if parsed.hostname.lower() == 'private-placeholder.cfx.re':
        return ('fileServer points to private-placeholder.cfx.re; '
                'check the endpoint returned by the server or memory reconstruction')
    return None


def download_direct(res, out_dir, session, log, stop_flag,
                    workers=6, retries=3, extract_rpf=True, delete_rpf=True):
    name  = res['name']
    files = res.get('files', {})
    fs    = res.get('fileServer', '').rstrip('/')
    if not files:
        log(f'  {name}: no files', 'warn'); return 0, 0
    endpoint_error = _invalid_file_server(fs)
    if endpoint_error:
        log(f'  [FILESERVER ERROR] {name}: {endpoint_error}', 'err')
        _write_log(f'  [FILESERVER ERROR] {name}: {endpoint_error}')
        return 0, len(files)

    os.makedirs(out_dir, exist_ok=True)
    tok = _tok_suffix(session)

    first_fname, first_hash = next(iter(files.items()))
    first_url = f'{fs}/{name}/{quote(first_fname)}?hash={first_hash}{tok}'
    if not _quick_exists(first_url, session):
        log(f'  {name}: ghost (404)', 'warn'); return -1, 0

    ok = fail = 0
    host = urlparse(fs).netloc

    def dl_file(fname, hsh, max_attempts=None):
        # True=ok, False=permanent fail, None=transient fail (retryable)
        if stop_flag(): return False
        fpath = os.path.join(out_dir, fname)
        os.makedirs(os.path.dirname(fpath), exist_ok=True)
        attempts = max_attempts if max_attempts is not None else retries
        last_err = None
        url = f'{fs}/{name}/{quote(fname)}?hash={hsh}{tok}'
        _write_log(f'    dl_direct url={fs}/{name}/{quote(fname)}?hash={hsh[:8]}...')
        for attempt in range(1, attempts + 1):
            _pace(host)
            try:
                r = session.get(url, timeout=30, stream=True)
                if r.status_code == 200:
                    _pace_relax(host)
                    with open(fpath, 'wb') as f:
                        for chunk in r.iter_content(65536):
                            if chunk: f.write(chunk)
                    log(f'  [OK] {name}/{fname}', 'ok')
                    return True
                elif r.status_code in (404, 410):
                    # Fallback: if the name contains %2B, try a literal +
                    encoded = quote(fname)
                    if '%2B' in encoded:
                        url_plus = f'{fs}/{name}/{encoded.replace("%2B", "+")  }?hash={hsh}{tok}'
                        try:
                            r2 = session.get(url_plus, timeout=30, stream=True)
                            if r2.status_code == 200:
                                with open(fpath, 'wb') as f:
                                    for chunk in r2.iter_content(65536):
                                        if chunk: f.write(chunk)
                                log(f'  [OK+] {name}/{fname}', 'ok')
                                return True
                        except Exception:
                            pass
                    log(f'  [{r.status_code}] {name}/{fname}', 'warn'); return False
                else:
                    body = r.text[:300].strip() if r.content else ''
                    log(f'  [HTTP {r.status_code}] {name}/{fname} attempt {attempt}/{attempts} — {body}', 'warn')
                    last_err = f'HTTP {r.status_code}'
                    if attempt < attempts:
                        time.sleep(2 * attempt)
            except Exception as e:
                last_err = e
                _pace_penalize(host)
                log(f'  [ERR attempt {attempt}/{attempts}] {name}/{fname}: {e}', 'warn')
                if attempt < attempts:
                    time.sleep(2 * attempt)
        log(f'  [FAIL] {name}/{fname} — {last_err}', 'err')
        return None  # transient — will be retried

    items = [(fn, val if isinstance(val, str) else val.get('hash', ''))
             for fn, val in files.items() if (val if isinstance(val, str) else val.get('hash', ''))]

    # Pass 1 — full concurrency
    failed_items = []
    with ThreadPoolExecutor(max_workers=workers) as exe:
        futs = {exe.submit(dl_file, fn, hsh): (fn, hsh) for fn, hsh in items}
        for f in as_completed(futs):
            r = f.result()
            if r is True:   ok += 1
            elif r is None: failed_items.append(futs[f])
            else:           fail += 1

    # Pass 2 — reduced concurrency (workers=2), cooldown 5s
    if failed_items and not stop_flag():
        log(f'  [{name}] {len(failed_items)} failures — retry in 5s (workers=2)...', 'warn')
        time.sleep(5)
        still_failed = []
        with ThreadPoolExecutor(max_workers=2) as exe:
            futs = {exe.submit(dl_file, fn, hsh, 4): (fn, hsh) for fn, hsh in failed_items}
            for f in as_completed(futs):
                r = f.result()
                if r is True:   ok += 1
                elif r is None: still_failed.append(futs[f])
                else:           fail += 1

        # Pass 3 — sequential, 2s between each request
        if still_failed and not stop_flag():
            log(f'  [{name}] {len(still_failed)} remaining — sequential retry...', 'warn')
            time.sleep(8)
            for idx3, (fn, hsh) in enumerate(still_failed):
                if stop_flag(): break
                r = dl_file(fn, hsh, 3)
                if r is True: ok += 1
                else:         fail += 1
                if idx3 < len(still_failed) - 1:
                    time.sleep(2)

    if extract_rpf:
        for fname in files:
            if fname.lower().endswith('.rpf'):
                rpf_path = os.path.join(out_dir, fname)
                if os.path.exists(rpf_path):
                    _unpack_rpf(rpf_path, out_dir, log, delete_after=delete_rpf)

    return ok, fail


def download_escrow(res, out_dir, session, log, stop_flag,
                    workers=6, retries=3, download_stream=True,
                    extract_rpf=True, delete_rpf=True):
    name = res['name']
    uri  = res.get('uri', '')
    if not uri or '#' not in uri:
        log(f'  {name}: invalid URI', 'err'); return 0, 0

    try:
        uri_data = base64.b64decode(uri.split('#')[1])
        xored    = uri_data[19:]
        iv       = uri_data[53:61]
        hmac_key = bytes(b ^ 0x69 for b in xored[:32])
    except Exception as e:
        log(f'  {name}: URI decode failed: {e}', 'err'); return 0, 0

    files = res.get('files', {})
    fs    = res.get('fileServer', '').rstrip('/')
    if not files:
        log(f'  {name}: no escrow files', 'warn'); return 0, 0
    endpoint_error = _invalid_file_server(fs)
    if endpoint_error:
        log(f'  [FILESERVER ERROR] {name}: {endpoint_error}', 'err')
        _write_log(f'  [FILESERVER ERROR] {name}: {endpoint_error}')
        return 0, len(files)

    os.makedirs(out_dir, exist_ok=True)
    tok = _tok_suffix(session)

    first_fname, first_hash = next(iter(files.items()))
    first_url = f'{fs}/{name}/{quote(first_fname)}?hash={first_hash}{tok}'
    if not _quick_exists(first_url, session):
        log(f'  {name}: ghost (404)', 'warn'); return -1, 0

    ok = fail = 0
    stream_dir = os.path.join(out_dir, 'stream')
    host = urlparse(fs).netloc

    def _dl_escrow(fname, hsh, out_path, label, max_attempts=None):
        # True=ok, False=permanent fail, None=transient fail (retryable)
        if stop_flag(): return False
        fkey = _hmac.new(hmac_key, fname.encode(), hashlib.sha256).digest()
        os.makedirs(os.path.dirname(out_path), exist_ok=True)
        attempts = max_attempts if max_attempts is not None else retries
        last_err = None
        url = f'{fs}/{name}/{quote(fname)}?hash={hsh}{tok}'
        _write_log(f'    dl_escrow url={fs}/{name}/{quote(fname)}?hash={hsh[:8] if hsh else ""}...')
        for attempt in range(1, attempts + 1):
            _pace(host)
            try:
                r = session.get(url, timeout=30, stream=True)
                if r.status_code != 200:
                    body = r.text[:300].strip() if r.content else ''
                    log(f'  [HTTP {r.status_code}] {name}/{label} attempt {attempt}/{attempts} — {body}', 'warn')
                    if r.status_code in (404, 410):
                        # Fallback: try a literal + if %2B is in the URL
                        encoded = quote(fname)
                        if '%2B' in encoded:
                            url_plus = f'{fs}/{name}/{encoded.replace("%2B", "+")}?hash={hsh}{tok}'
                            try:
                                r2 = session.get(url_plus, timeout=30, stream=True)
                                if r2.status_code == 200:
                                    raw = b''.join(r2.iter_content(65536))
                                    try:
                                        dec = ChaCha20.new(key=fkey, nonce=iv).decrypt(raw)
                                    except Exception:
                                        dec = ChaCha20.new(key=fkey, nonce=iv[:8]).decrypt(raw)
                                    with open(out_path, 'wb') as f:
                                        f.write(dec)
                                    log(f'  [OK+] {name}/{label}', 'ok')
                                    return True
                            except Exception:
                                pass
                        return False
                    last_err = f'HTTP {r.status_code}'
                    if attempt < attempts:
                        time.sleep(2 * attempt)
                    continue
                _pace_relax(host)
                raw = b''.join(r.iter_content(65536))
                try:
                    dec = ChaCha20.new(key=fkey, nonce=iv).decrypt(raw)
                except Exception:
                    dec = ChaCha20.new(key=fkey, nonce=iv[:8]).decrypt(raw)
                if out_path.lower().endswith('.rpf') and not dec.startswith(b'RPF'):
                    log(f'  [invalid RPF] {name}/{label}', 'warn'); return False
                with open(out_path, 'wb') as f:
                    f.write(dec)
                log(f'  [OK] {name}/{label}', 'ok')
                return True
            except Exception as e:
                last_err = e
                _pace_penalize(host)
                log(f'  [ERR attempt {attempt}/{attempts}] {name}/{label}: {e}', 'warn')
                if attempt < attempts:
                    time.sleep(2 * attempt)
        log(f'  [FAIL] {name}/{label} — {last_err}', 'err')
        return None  # transient (timeout, network)

    def _run_passes(task_list, label_prefix):
        nonlocal ok, fail
        # Pass 1 — full concurrency
        failed = []
        with ThreadPoolExecutor(max_workers=workers) as exe:
            futs = {exe.submit(_dl_escrow, fn, hsh, path, lbl): (fn, hsh, path, lbl)
                    for fn, hsh, path, lbl in task_list}
            for f in as_completed(futs):
                r = f.result()
                if r is True:   ok += 1
                elif r is None: failed.append(futs[f])
                else:           fail += 1

        # Pass 2 — workers=2, cooldown 5s
        if failed and not stop_flag():
            log(f'  [{name}] {len(failed)} {label_prefix} failures — retry in 5s (workers=2)...', 'warn')
            time.sleep(5)
            still = []
            with ThreadPoolExecutor(max_workers=2) as exe:
                futs = {exe.submit(_dl_escrow, fn, hsh, path, lbl, 4): (fn, hsh, path, lbl)
                        for fn, hsh, path, lbl in failed}
                for f in as_completed(futs):
                    r = f.result()
                    if r is True:   ok += 1
                    elif r is None: still.append(futs[f])
                    else:           fail += 1

            # Pass 3 — sequential, 2s between each request
            if still and not stop_flag():
                log(f'  [{name}] {len(still)} {label_prefix} remaining — sequential retry...', 'warn')
                time.sleep(8)
                for idx3, (fn, hsh, path, lbl) in enumerate(still):
                    if stop_flag(): break
                    r = _dl_escrow(fn, hsh, path, lbl, 3)
                    if r is True: ok += 1
                    else:         fail += 1
                    if idx3 < len(still) - 1:
                        time.sleep(2)

    # Merge regular files + stream files into a single pass (same as before)
    def _make_hash(val):
        return val if isinstance(val, str) else val.get('hash', '')

    items = [(fn, _make_hash(val), os.path.join(out_dir, fn), fn)
             for fn, val in files.items() if _make_hash(val)]

    all_tasks = list(items)
    if download_stream:
        stream_files = res.get('streamFiles', {})
        if stream_files:
            os.makedirs(stream_dir, exist_ok=True)
            all_tasks += [(fn, _make_hash(val), os.path.join(stream_dir, fn), f'stream/{fn}')
                          for fn, val in stream_files.items() if _make_hash(val)]

    _run_passes(all_tasks, 'files+stream')

    if extract_rpf:
        for fn, _, path, _ in items:
            if fn.lower().endswith('.rpf') and os.path.exists(path):
                _unpack_rpf(path, out_dir, log, delete_after=delete_rpf)

    return ok, fail


def _unpack_rpf(rpf_path, out_dir, log, delete_after=True):
    fname = os.path.basename(rpf_path)
    try:
        with open(rpf_path, 'rb') as f:
            data = f.read()
        if len(data) < 2064:
            log(f'  [RPF] {fname}: too small ({len(data)} bytes)', 'warn'); return
        if data[:4] != b'RPF2':
            log(f'  [RPF] {fname}: unknown magic {data[:4]!r}', 'warn'); return
        entry_count = struct.unpack_from('<I', data, 8)[0]
        if entry_count == 0 or entry_count > 100000:
            log(f'  [RPF] {fname}: invalid entry_count ({entry_count})', 'warn'); return
        toc_base  = 2048
        name_base = toc_base + entry_count * 16

        def read_name(off):
            s = name_base + off
            e = data.find(b'\x00', s)
            return data[s:e if e != -1 else s+256].decode('utf-8', 'ignore')

        entries = []
        for i in range(entry_count):
            b  = toc_base + i * 16
            no = struct.unpack_from('<I', data, b)[0]
            v1 = struct.unpack_from('<I', data, b+4)[0]
            v2 = struct.unpack_from('<I', data, b+8)[0]
            v3 = struct.unpack_from('<I', data, b+12)[0]
            if v2 & 0x80000000:
                entries.append({'dir': True,  'name': read_name(no),
                                 'first': v2 & 0x7FFFFFFF, 'count': v3})
            else:
                entries.append({'dir': False, 'name': read_name(no),
                                 'offset': v2, 'size': v1})

        extracted = [0]
        def extract(idx, directory):
            if idx >= len(entries): return
            e = entries[idx]
            if e['dir']:
                sub = os.path.join(directory, e['name']) if e['name'] and e['name'] != '/' else directory
                os.makedirs(sub, exist_ok=True)
                for i in range(e['count']): extract(e['first'] + i, sub)
            else:
                if not e['name'] or e['size'] == 0: return
                if e['offset'] + e['size'] > len(data): return
                dst = os.path.join(directory, e['name'])
                parent = os.path.dirname(dst)
                if parent: os.makedirs(parent, exist_ok=True)
                with open(dst, 'wb') as wf:
                    wf.write(data[e['offset']:e['offset']+e['size']])
                extracted[0] += 1

        if not entries or not entries[0]['dir']:
            log(f'  [RPF] {fname}: root entry not found', 'warn'); return
        for i in range(entries[0]['count']):
            extract(entries[0]['first'] + i, out_dir)

        if extracted[0]:
            log(f'  [RPF] {fname} → {extracted[0]} files extracted', 'ok')
            if delete_after:
                try: os.remove(rpf_path)
                except Exception: pass
        else:
            log(f'  [RPF] {fname}: 0 files extracted', 'warn')
    except Exception as ex:
        log(f'  [RPF ERR] {fname}: {ex}', 'err')


# ═══════════════════════════════════════════════════════════════════════════
# Application GUI — 4 pages: Interface | Connection | Tools | Settings
# ═══════════════════════════════════════════════════════════════════════════

class App(ctk.CTk):

    # ── Init ──────────────────────────────────────────────────────────────
    def __init__(self):
        # Give Windows this app its own taskbar identity instead of inheriting
        # Python/CustomTkinter/PyInstaller's generic icon identity.
        if sys.platform == 'win32':
            try:
                ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(
                    'CNC.Dumper.Realkhmershyyt'
                )
            except Exception:
                pass

        super().__init__()
        self.title('CNC Dumper • Realkhmershyyt')
        self.geometry('1240x800')
        self.minsize(1040, 680)
        self.configure(fg_color=BG)
        self.resizable(True, True)

        # CNC logo for window/titlebar/taskbar and sidebar branding.
        self._logo_pil = _load_cnc_logo_image()
        self._logo_icon_tk = None
        if self._logo_pil is not None:
            try:
                icon_img = self._logo_pil.copy()
                icon_img.thumbnail((64, 64), Image.Resampling.LANCZOS)
                icon_buf = BytesIO()
                icon_img.save(icon_buf, format='PNG')
                self._logo_icon_tk = tk.PhotoImage(
                    data=base64.b64encode(icon_buf.getvalue()).decode('ascii')
                )
                self.iconphoto(True, self._logo_icon_tk)
            except Exception:
                self._logo_icon_tk = None

        self.fivem_pid = tk.IntVar(value=0)
        self.token     = ''
        self.ticket    = ''
        self.game_mode = 'fivem'    # 'fivem' | 'redm' — detected from the active process
        self.game_name = 'gta5'     # value sent in the Cfx-Game-Name header
        self.resources = []
        self.dumping   = False
        self._stop     = False
        self._session  = None
        self._log_q    = queue.Queue()
        self._res_vars = {}
        self.license_key      = ''   # client's personal key — used for TOOLS API calls
        self.license_features = []   # features unlocked by the license plan
        # Clear the log at startup
        try:
            open(_LOG_FILE, 'w', encoding='utf-8').close()
        except Exception:
            pass

        self._settings_file = os.path.join(_APP_DIR, 'settings.json')
        self._cfg = self._load_settings()
        self._server_host = ''
        _apply_theme_globals()
        # Single source for the output folder — shared between Interface and Settings
        self._sv_out_dir = tk.StringVar(
            value=self._cfg.get('out_dir', os.path.join(_APP_DIR, 'Output'))
        )

        self._build_ui()
        self._apply_style()
        self._show_page('interface')

        self.protocol('WM_DELETE_WINDOW', self._on_close)
        threading.Thread(target=self._detect_loop, daemon=True).start()
        self._drain_log()
        self.after(500, self._check_license)

    # ── Settings ──────────────────────────────────────────────────────────
    def _load_settings(self):
        default_out = os.path.join(_APP_DIR, 'Output')
        d = {
            'out_dir':         default_out,
            'workers':         6,
            'res_workers':     1,
            'retries':         3,
            'extract_rpf':     True,
            'download_stream': True,
            'delete_rpf':      True,
        }
        try:
            with open(self._settings_file, 'r', encoding='utf-8') as f:
                d.update(json.load(f))
        except Exception:
            pass

        # Force out_dir to stay next to the .exe if the saved path
        # points to a temporary folder or no longer exists
        saved = d.get('out_dir', '')
        import tempfile as _tf
        temp_root = _tf.gettempdir().lower()
        bad_indicators = [temp_root, '_mei', 'appdata\\local\\temp', '/tmp/']
        is_temp = any(ind in saved.lower() for ind in bad_indicators)
        if is_temp or not saved:
            d['out_dir'] = default_out

        return d

    def _save_settings(self, from_ui=True):
        try:
            if from_ui:
                self._cfg['out_dir']         = self._sv_out_dir.get().strip()
                self._cfg['workers']         = max(1, min(32, int(self._sv_workers.get() or 6)))
                self._cfg['res_workers']     = max(1, min(10, int(self._sv_res_workers.get() or 3)))
                self._cfg['retries']         = max(1, min(10, int(self._sv_retries.get() or 3)))
                self._cfg['extract_rpf']     = bool(self._bv_extract.get())
                self._cfg['download_stream'] = bool(self._bv_stream.get())
                self._cfg['delete_rpf']      = bool(self._bv_delete_rpf.get())
            else:
                self._cfg['out_dir'] = self._sv_out_dir.get().strip()
            with open(self._settings_file, 'w', encoding='utf-8') as f:
                json.dump(self._cfg, f, indent=2, ensure_ascii=False)
            if from_ui:
                self._log('Settings saved', 'ok')
                self._lbl_save_status.config(text='  Saved ✓', fg=GRN)
                self.after(3000, lambda: self._lbl_save_status.config(text='', fg=FG2))
        except Exception as e:
            self._log(f'Save error: {e}', 'err')

    def _on_close(self):
        try:
            self._save_settings(from_ui=False)
        except Exception:
            pass
        self.destroy()

    # ── UI structure ──────────────────────────────────────────────────────
    def _build_ui(self):
        self._build_statusbar()
        main = tk.Frame(self, bg=BG)
        main.pack(fill='both', expand=True)
        self._build_nav_sidebar(main)
        content = tk.Frame(main, bg=BG)
        content.pack(side='left', fill='both', expand=True)
        self._pages = {
            'interface':  self._build_page_interface(content),
            'connexion':  self._build_page_connexion(content),
            'outils':     self._build_page_outils(content),
            'parametres': self._build_page_parametres(content),
        }

    # ── Status bar (always visible, bottom) ───────────────────────────────
    def _build_statusbar(self):
        # Slim persistent status strip.  All status widgets keep their original names.
        bar = ctk.CTkFrame(self, fg_color='#080001', height=38, corner_radius=0,
                           border_width=1, border_color=BDR_RED)
        bar.pack(fill='x', side='bottom')
        bar.pack_propagate(False)

        left = ctk.CTkFrame(bar, fg_color='transparent')
